(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.MohCore=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const fail=m=>{throw Error(m);};
function text(v,max,label,empty=true){if(typeof v!=='string'||v.length>max||(!empty&&!v.trim()))fail('שדה לא תקין בגיבוי: '+label);return v;}
function id(v){if(typeof v!=='string'||!/^[-\w]{1,100}$/.test(v))fail('מזהה לא תקין בגיבוי');return v;}
function number(v,min,max){if(!Number.isInteger(v)||v<min||v>max)fail('מספר גרסה לא תקין בגיבוי');return v;}
function url(v){if(!v)return '';try{const u=new URL(v);if(u.protocol!=='https:'||u.username||u.password)fail('הקישורים חייבים להיות HTTPS');return u.href;}catch{fail('קישור לא תקין בגיבוי');}}
function visual(v){if(!v||!Array.isArray(v.points)||v.points.length!==3)fail('נדרשים שלושה מסרים בתמונה');return {title:text(v.title,60,'כותרת תמונה'),points:v.points.map(p=>text(p,90,'מסר בתמונה'))};}
function review(r,version){if(!r)return null;if(!r.scores||!Array.isArray(r.findings)||r.findings.length>50)fail('דוח ביקורת לא תקין');const scores={};for(const k of ['accuracy','clarity','usefulness','voice'])scores[k]=number(r.scores[k],1,5);return {version:number(r.version,1,version),reviewer:text(r.reviewer,150,'בודק'),type:['ai_session','human'].includes(r.type)?r.type:'human',scores,blocking:!!r.blocking,findings:r.findings.map(v=>text(v,4000,'ממצא'))};}
function validateBackup(input){if(!input||input.schemaVersion!==1||!Array.isArray(input.sources)||!Array.isArray(input.drafts)||input.sources.length>100||input.drafts.length>200)fail('זה אינו גיבוי נתמך של מוח AI');const ids=new Set();const sources=input.sources.map(s=>{const sid=id(s.id);if(ids.has(sid))fail('מקור כפול בגיבוי');ids.add(sid);const content=text(s.content,150000,'תוכן מקור',false),excerpt=text(s.excerpt||'',500,'קטע ראיה');if(excerpt&&!content.includes(excerpt))fail('קטע הראיה אינו נמצא במקור');return {id:sid,title:text(s.title,160,'כותרת מקור',false),url:url(s.url),content,claim:text(s.claim||'',600,'טענה'),excerpt,verified:!!s.verified&&!!excerpt&&!!s.claim,basis:s.basis==='transcript'?'transcript':'full_text',coverage:s.coverage==='selected_excerpts'?'selected_excerpts':'supplied_content',createdAt:text(s.createdAt,80,'תאריך קליטה'),publishedAt:s.publishedAt?text(s.publishedAt,80,'תאריך מקור'):null};});const draftIds=new Set();const drafts=input.drafts.map(d=>{const did=id(d.id);if(draftIds.has(did))fail('טיוטה כפולה בגיבוי');draftIds.add(did);const sourceId=id(d.sourceId);if(!ids.has(sourceId))fail('חסר מקור לטיוטה');const version=number(d.version,1,10000);if(!Array.isArray(d.history)||d.history.length>100)fail('היסטוריית גרסאות ארוכה מדי');return {id:did,sourceId,title:text(d.title,160,'כותרת טיוטה',false),text:text(d.text,30000,'פוסט'),version,origin:d.origin==='assistant_session'?'assistant_session':'manual',visual:visual(d.visual),review:review(d.review,version),approvedVersion:d.approvedVersion===version?version:null,createdAt:text(d.createdAt,80,'מועד יצירה'),updatedAt:text(d.updatedAt,80,'מועד עדכון'),history:d.history.map(h=>({version:number(h.version,1,version),title:text(h.title||d.title,160,'כותרת קודמת'),text:text(h.text,30000,'גרסה קודמת'),at:text(h.at,80,'תאריך גרסה')}))};});return {schemaVersion:1,sources,drafts,voiceExamples:text(input.voiceExamples||'',20000,'דוגמאות כתיבה'),updatedAt:text(input.updatedAt||new Date().toISOString(),80,'תאריך עדכון')};}
function canApprove(d,s,unsaved=false){if(unsaved)return 'שמרו קודם את השינויים כגרסה חדשה.';if(!d.text.trim())return 'כתבו קודם פוסט.';if(!s||!s.verified||!s.excerpt||!s.claim||!s.content.includes(s.excerpt))return 'כדי לאשר צריך מקור עם טענה, קטע ראיה ואימות ידני.';if(!d.review||d.review.version!==d.version)return 'נדרשת ביקורת על הגרסה הנוכחית.';if(d.review.blocking||Object.values(d.review.scores).some(n=>n<4))return 'יש עדיין תיקונים או ציונים נמוכים בביקורת. תקנו ובדקו שוב.';return '';}
return {validateBackup,canApprove};});
